import { writeFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const formulasDir = join(__dirname, '..', 'src', 'data', 'formulas');
mkdirSync(formulasDir, { recursive: true });

const NOW = '2025-01-01T00:00:00.000Z';

// Compact format: [id, cat, ch, topic, name, formula, latex, desc, var1, var2, ..., units, conditions, notes, jeeTip?, mistakes, tags, synonyms, importance, difficulty, exam, freq?]
// Each var is [sym, desc, unit?]
function mk(subject, d) {
  const [id, category, chapter, topic, name, formula, latex, description, ...rest] = d;
  // Collect all array elements as variables, then scalar fields follow
  let varEnd = 0;
  while (varEnd < rest.length && Array.isArray(rest[varEnd])) {
    varEnd++;
  }
  // Filter out placeholder variables like ['—'] that have no description.
  // Keep only valid variable tuples: [symbol, description, unit?]
  const variables = rest
    .slice(0, varEnd)
    .filter(v => Array.isArray(v) && v.length >= 2 && typeof v[1] === 'string' && v[1].length > 0 && v[0] !== '—')
    .map(v => ({ symbol: v[0], description: v[1], ...(v[2] ? { unit: v[2] } : {}) }));
  let remaining = rest.slice(varEnd);
  
  // Check if jeeTip (4th field, index 3) is an array - if so, jeeTip is missing
  let units, conditions, notes, jeeTip, commonMistakes, tags, synonyms, importance, difficulty, examRelevance, freq;
  if (remaining.length >= 4 && Array.isArray(remaining[3])) {
    [units, conditions, notes, commonMistakes, tags, synonyms, importance, difficulty, examRelevance, freq] = remaining;
    jeeTip = undefined;
  } else {
    [units, conditions, notes, jeeTip, commonMistakes, tags, synonyms, importance, difficulty, examRelevance, freq] = remaining;
  }
  
  // Ensure array fields are arrays
  const cm = Array.isArray(commonMistakes) ? commonMistakes : (commonMistakes ? [commonMistakes] : []);
  const tg = Array.isArray(tags) ? tags : (tags ? [tags] : []);
  const sy = Array.isArray(synonyms) ? synonyms : (synonyms ? [synonyms] : []);
  
  return { id, subject, category, chapter, topic, name, formula, latex, description, variables, units, conditions, notes, jeeTip, commonMistakes: cm, tags: tg, synonyms: sy, importance, difficulty, examRelevance, frequentlyUsed: freq || false, createdAt: NOW, updatedAt: NOW };
}

