// Generate files
const physicsFormulas = phy.map(d => mk('Physics', d));
const chemistryFormulas = chem.map(d => mk('Chemistry', d));
const mathFormulas = math.map(d => mk('Mathematics', d));

const header = `// AUTO-GENERATED by scripts/generate-formulas.mjs — DO NOT EDIT MANUALLY
import type { Formula } from '../../types';

export const physicsFormulas: Formula[] = `;

const chemHeader = `// AUTO-GENERATED by scripts/generate-formulas.mjs — DO NOT EDIT MANUALLY
import type { Formula } from '../../types';

export const chemistryFormulas: Formula[] = `;

const mathHeader = `// AUTO-GENERATED by scripts/generate-formulas.mjs — DO NOT EDIT MANUALLY
import type { Formula } from '../../types';

export const mathFormulas: Formula[] = `;

writeFileSync(join(formulasDir, 'physics.ts'), header + JSON.stringify(physicsFormulas, null, 2) + ';\n');
writeFileSync(join(formulasDir, 'chemistry.ts'), chemHeader + JSON.stringify(chemistryFormulas, null, 2) + ';\n');
writeFileSync(join(formulasDir, 'mathematics.ts'), mathHeader + JSON.stringify(mathFormulas, null, 2) + ';\n');

// Index file
const indexContent = `// AUTO-GENERATED by scripts/generate-formulas.mjs — DO NOT EDIT MANUALLY
import type { Formula, FormulaSubject } from '../../types';
import { physicsFormulas } from './physics';
import { chemistryFormulas } from './chemistry';
import { mathFormulas } from './mathematics';

export const allFormulas: Formula[] = [
  ...physicsFormulas,
  ...chemistryFormulas,
  ...mathFormulas,
];

export { physicsFormulas, chemistryFormulas, mathFormulas };

export function getFormulaById(id: string): Formula | undefined {
  return allFormulas.find((f) => f.id === id);
}

export function getFormulaCategories(subject: FormulaSubject): string[] {
  return [...new Set(allFormulas.filter((f) => f.subject === subject).map((f) => f.category))].sort();
}

export function getChaptersByCategory(subject: FormulaSubject, category: string): string[] {
  return [
    ...new Set(
      allFormulas
        .filter((f) => f.subject === subject && f.category === category)
        .map((f) => f.chapter),
    ),
  ].sort((a, b) => a.localeCompare(b));
}
`;
writeFileSync(join(formulasDir, 'index.ts'), indexContent);

console.log(`Generated ${physicsFormulas.length} Physics, ${chemistryFormulas.length} Chemistry, ${mathFormulas.length} Mathematics formulas.`);
console.log(`Total: ${physicsFormulas.length + chemistryFormulas.length + mathFormulas.length} formulas.`);